module settle_bills (\n    input clk,\n    input rst_n,\n    input start,\n    input [2:0] receipt_a,\n    input [2:0] receipt_b,\n    input [9:0] receipt_p,\n    input receipt_valid,\n    input last,\n    output reg [3:0] result,\n    output reg done\n);\n\n// State parameters\nlocalparam [3:0] IDLE               = 4'd0;\nlocalparam [3:0] PROC_RECEIPTS      = 4'd1;\nlocalparam [3:0] COUNT_NONZERO      = 4'd2;\nlocalparam [3:0] FIND_COMP_START    = 4'd3;\nlocalparam [3:0] FIND_COMP_MAIN     = 4'd4;\nlocalparam [3:0] PROPAGATE_COMP     = 4'd5;\nlocalparam [3:0] FINISH             = 4'd6;\n\nreg [3:0] state, next_state;\nreg [31:0] balance [0:7];  // 8 people, 32-bit balances\nreg [7:0] adjacency [0:7]; // 8x8 adjacency matrix\nreg [7:0] visited;\nreg [3:0] non_zero_count;\nreg [3:0] component_count;\nreg [2:0] idx, i, j, k;   // Counters\nreg propagation_changed;\n\n// Initialization\ninteger init_idx;\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        state <= IDLE;\n        done <= 1'b0;\n        result <= 4'd0;\n        non_zero_count <= 4'd0;\n        component_count <= 4'd0;\n        visited <= 8'd0;\n        propagation_changed <= 1'b0;\n        \n        // Initialize arrays\n        for (init_idx = 0; init_idx < 8; init_idx = init_idx + 1) begin\n            balance[init_idx] <= 32'd0;\n            adjacency[init_idx] <= 8'd0;\n        end\n    end else begin\n        state <= next_state;\n    end\nend\n\n// State transitions\nalways @(*) begin\n    next_state = state;\n    case (state)\n        IDLE:          if (start)           next_state = PROC_RECEIPTS;\n        PROC_RECEIPTS: if (last)            next_state = COUNT_NONZERO;\n        COUNT_NONZERO: if (idx == 3'd7)     next_state = FIND_COMP_START;\n        FIND_COMP_START:                    next_state = FIND_COMP_MAIN;\n        FIND_COMP_MAIN: begin\n            if (idx == 3'd7)             next_state = FINISH;\n            else if (visited[idx] == 1'b0 && balance[idx] != 32'd0)\n                                        next_state = PROPAGATE_COMP;\n        end\n        PROPAGATE_COMP: if (!propagation_changed) next_state = FIND_COMP_MAIN;\n        FINISH:                         next_state = IDLE;\n        default:                        next_state = IDLE;\n    endcase\nend\n\n// State operations\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        // Handled in initialization\n    end else begin\n        done <= 1'b0;\n        case (state)\n            PROC_RECEIPTS: if (receipt_valid) begin\n                // Update balances\n                balance[receipt_a] <= balance[receipt_a] - receipt_p;\n                balance[receipt_b] <= balance[receipt_b] + receipt_p;\n                // Update adjacency matrix\n                adjacency[receipt_a][receipt_b] <= 1'b1;\n                adjacency[receipt_b][receipt_a] <= 1'b1;\n            end\n            \n            COUNT_NONZERO: begin\n                idx <= idx + 3'd1;\n                if (balance[idx] != 32'd0) non_zero_count <= non_zero_count + 4'd1;\n            end\n            \n            FIND_COMP_START: begin\n                idx <= 3'd0;\n                component_count <= 4'd0;\n            end\n            \n            FIND_COMP_MAIN: begin\n                idx <= idx + 3'd1;\n                if (visited[idx] == 1'b0 && balance[idx] != 32'd0) begin\n                    component_count <= component_count + 4'd1;\n                    visited[idx] <= 1'b1;\n                    j <= idx;\n                    propagation_changed <= 1'b1;\n                end\n            end\n            \n            PROPAGATE_COMP: begin\n                propagation_changed <= 1'b0;\n                for (k = 0; k < 8; k = k + 1) begin\n                    if (adjacency[j][k] == 1'b1 && visited[k] == 1'b0 && balance[k] != 32'd0) begin\n                        visited[k] <= 1'b1;\n                        propagation_changed <= 1'b1;\n                    end\n                end\n            end\n            \n            FINISH: begin\n                result <= non_zero_count - component_count;\n                done <= 1'b1;\n            end\n        endcase\n    end\nend\n\nendmodule